let orders = JSON.parse(localStorage.getItem("orders")) || [];
let currentPaymentMode = "Cash";

function saveOrders() {
  localStorage.setItem("orders", JSON.stringify(orders));
}

function setPaymentMode(mode) {
  currentPaymentMode = mode;
  document.getElementById("paymentMode").innerText = mode;
}

function addItem(name, price) {
  let order = {
    name: name,
    price: price,
    paymentMode: currentPaymentMode,
    time: new Date().toLocaleTimeString()
  };

  orders.push(order);
  saveOrders();
  updateUI();
}

function updateUI() {
  let total = 0;
  let cashTotal = 0;
  let upiTotal = 0;
  let itemCounts = {};

  orders.forEach(o => {
    total += o.price;

    if (o.paymentMode === "Cash") {
      cashTotal += o.price;
    } else if (o.paymentMode === "UPI") {
      upiTotal += o.price;
    }

    if (!itemCounts[o.name]) {
      itemCounts[o.name] = { qty: 0, amount: 0 };
    }

    itemCounts[o.name].qty += 1;
    itemCounts[o.name].amount += o.price;
  });

  document.getElementById("total").innerText = total;
  document.getElementById("count").innerText = orders.length;
  document.getElementById("cashTotal").innerText = cashTotal;
  document.getElementById("upiTotal").innerText = upiTotal;
  document.getElementById("paymentMode").innerText = currentPaymentMode;

  let list = document.getElementById("orders");
  list.innerHTML = "";

  orders.slice().reverse().forEach(o => {
    let li = document.createElement("li");
    li.innerText = `${o.name} - ₹${o.price} - ${o.paymentMode} (${o.time})`;
    list.appendChild(li);
  });

  let summaryList = document.getElementById("itemSummary");
  summaryList.innerHTML = "";

  Object.keys(itemCounts).forEach(name => {
    let li = document.createElement("li");
    li.innerText = `${name} - Qty: ${itemCounts[name].qty} - ₹${itemCounts[name].amount}`;
    summaryList.appendChild(li);
  });
}

function undo() {
  let last = orders.pop();
  if (last) {
    saveOrders();
    updateUI();
  }
}

function clearAll() {
  orders = [];
  saveOrders();
  updateUI();
}

updateUI();
